#include <cctype>
#include <cstddef>
#include <format>
#include <iostream>
#include <string_view>

[[nodiscard]] bool is_palindrome(std::string_view s) {
  // The <cctype> functions need an unsigned char value: a negative char is undefined behaviour.
  const auto letter = [](char c) { return std::isalpha(static_cast<unsigned char>(c)) != 0; };
  const auto lower = [](char c) { return std::tolower(static_cast<unsigned char>(c)); };
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = std::ssize(s) - 1;  // the last unchecked character; -1 for an empty string
  while (lo < hi) {
    if (!letter(s[lo])) {
      ++lo;
    } else if (!letter(s[hi])) {
      --hi;
    } else if (lower(s[lo]) != lower(s[hi])) {
      return false;
    } else {
      ++lo;
      --hi;
    }
  }
  return true;
}

int main() {
  std::cout << std::format("{} {} {} {}\n", is_palindrome("A man, a plan, a canal: Panama"),
                           is_palindrome("race a car"), is_palindrome(""), is_palindrome(".,"));
}

