#include <algorithm>
#include <cctype>
#include <format>
#include <iostream>
#include <ranges>
#include <string_view>

[[nodiscard]] bool is_palindrome(std::string_view s) {
  const auto letter = [](char c) { return std::isalpha(static_cast<unsigned char>(c)) != 0; };
  const auto lower = [](char c) { return std::tolower(static_cast<unsigned char>(c)); };
  auto letters = s | std::views::filter(letter) | std::views::transform(lower);
  return std::ranges::equal(letters, letters | std::views::reverse);
}

int main() {
  std::cout << std::format("{} {} {} {}\n", is_palindrome("A man, a plan, a canal: Panama"),
                           is_palindrome("race a car"), is_palindrome(""), is_palindrome(".,"));
}

