using IndexPair = std::pair<std::ptrdiff_t, std::ptrdiff_t>;

[[nodiscard]] std::optional<IndexPair> pair_sum(std::span<const int> v, int target) {
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = std::ssize(v) - 1;
  while (lo < hi) {
    const std::int64_t sum = std::int64_t{v[lo]} + v[hi];  // two ints can pass the int limit
    if (sum == target) return IndexPair{lo, hi};
    if (sum < target) {
      ++lo;  // v[lo] is too small even with the largest partner left
    } else {
      --hi;  // v[hi] is too large even with the smallest partner left
    }
  }
  return std::nullopt;
}

[[nodiscard]] std::string show(const std::optional<IndexPair>& pair) {
  return pair ? std::format("{{{}, {}}}", pair->first, pair->second) : "no value";
}

int main() {
  const std::vector<int> v{1, 3, 4, 6, 8, 11};
  const std::vector<int> small{1, 2};
  const std::vector<int> empty;
  std::cout << show(pair_sum(v, 10)) << ' ' << show(pair_sum(small, 10)) << ' ' << show(pair_sum(empty, 10)) << '\n';
}

#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <ranges>
#include <string_view>

[[nodiscard]] bool reads_same_reversed(std::string_view s) {
  return std::ranges::equal(s, s | std::views::reverse);
}

[[nodiscard]] bool almost_palindrome(std::string_view s) {
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = std::ssize(s) - 1;
  while (lo < hi && s[lo] == s[hi]) {
    ++lo;
    --hi;
  }
  if (lo >= hi) return true;
  // s[lo] != s[hi]: delete one of them, and what is left of s[lo..hi] must read the same both ways.
  return reads_same_reversed(s.substr(lo + 1, hi - lo)) || reads_same_reversed(s.substr(lo, hi - lo));
}

int main() {
  std::cout << std::format("{} {} {} {} {}\n", almost_palindrome("abca"), almost_palindrome("abc"),
                           almost_palindrome("deeee"), almost_palindrome(""), almost_palindrome("ab"));
}

#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <vector>

// Keeps at most `keep` copies of each value of a sorted vector, in order, and shrinks the vector.
void dedupe_sorted(std::vector<int>& v, std::ptrdiff_t keep = 1) {
  if (keep < 1) {  // no copies at all; the loop below needs keep >= 1
    v.clear();
    return;
  }
  std::ptrdiff_t write = 0;
  for (std::ptrdiff_t read = 0; read < std::ssize(v); ++read)
    if (write < keep || v[read] != v[write - keep]) v[write++] = v[read];
  v.erase(v.begin() + write, v.end());
}

[[nodiscard]] std::string show(std::span<const int> v) {
  std::string out = "{";
  for (std::string_view separator; const int x : v) {
    out += std::format("{}{}", separator, x);
    separator = ", ";
  }
  return out + "}";
}

int main() {
  const std::vector<int> input{1, 1, 2, 3, 3, 3};
  std::vector<int> once = input;
  std::vector<int> twice = input;
  std::vector<int> library = input;
  std::vector<int> empty;
  dedupe_sorted(once);
  dedupe_sorted(twice, 2);
  dedupe_sorted(empty);
  const auto tail = std::ranges::unique(library);  // the named form of the one-copy version
  library.erase(tail.begin(), tail.end());
  std::cout << std::format("{} {} {} {}\n", show(once), show(twice), show(library), show(empty));
}

#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <format>
#include <iostream>
#include <limits>
#include <optional>
#include <span>
#include <string>
#include <vector>

[[nodiscard]] std::optional<std::int64_t> closest_pair_sum(std::span<const int> v, int target) {
  std::optional<std::int64_t> best;
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = std::ssize(v) - 1;
  while (lo < hi) {
    const std::int64_t sum = std::int64_t{v[lo]} + v[hi];
    if (!best || std::abs(sum - target) < std::abs(*best - target)) best = sum;
    if (sum == target) break;
    if (sum < target) {
      ++lo;
    } else {
      --hi;
    }
  }
  return best;
}

[[nodiscard]] std::string show(const std::optional<std::int64_t>& sum) {
  return sum ? std::to_string(*sum) : "no value";
}

int main() {
  constexpr int big = std::numeric_limits<int>::max();
  const std::vector<int> v{-4, -1, 1, 2, 5};
  const std::vector<int> one{5};
  const std::vector<int> large{big - 1, big};
  std::cout << std::format("{} {} {} {}\n", show(closest_pair_sum(v, 3)), show(closest_pair_sum(v, 20)),
                           show(closest_pair_sum(one, 5)), show(closest_pair_sum(large, 0)));
}

#include <cstddef>
#include <cstdint>
