// Right: the loop stops when fewer than two elements are left.
[[nodiscard]] bool has_pair(std::span<const int> v, int target) {
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = std::ssize(v) - 1;
  while (lo < hi) {
    const std::int64_t sum = std::int64_t{v[lo]} + v[hi];
    if (sum == target) return true;
    if (sum < target) {
      ++lo;
    } else {
      --hi;
    }
  }
  return false;
}

// Wrong: when lo == hi, the one element left is paired with itself.
[[nodiscard]] bool has_pair_off_by_one(std::span<const int> v, int target) {
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = std::ssize(v) - 1;
  while (lo <= hi) {
    const std::int64_t sum = std::int64_t{v[lo]} + v[hi];
    if (sum == target) return true;
    if (sum < target) {
      ++lo;
    } else {
      --hi;
    }
  }
  return false;
}

int main() {
  const std::vector<int> v{1, 5, 8};
  std::cout << std::format("lo <= hi says {}, lo < hi says {}\n", has_pair_off_by_one(v, 10), has_pair(v, 10));
}
